import java.util.*;

public class Main {
    void fullPyramid(int n) {
        for (int i = 1; i <= n; i++) {                // row i needs n - i spaces then 2i - 1 stars
            int gap = n - i;
            for (int j = 0; j < n + i - 1; j++) {       // check every column this row actually uses
                if (j < gap) {
                    System.out.print(" ");                 // still inside the leading gap
                } else {
                    System.out.print("*");                 // inside the star region
                }
            }
            System.out.println();                      // move to the next line after the row
        }
    }

    public static void main(String[] args) {
        Main solution = new Main();
        solution.fullPyramid(4);
    }
}

